	@Override
	public void close() throws SailException {
		if (Thread.currentThread() == tripleStoreOwnerThread
				|| Thread.currentThread() == mapGrowthCoordinator.growthThread
				|| sinkStoreAccessLock.isHeldByCurrentThread() || publicationContext.get() != null) {
			throw new SailException("An active LMDB native/publication owner cannot close its own store");
		}
		initialImportClosing = true;
		Throwable failure = null;
		failure = attemptClose(failure, this::awaitPostReadyInitializationForShutdown);
		failure = attemptClose(failure, queryResultCache::clear);
		failure = attemptClose(failure, () -> NativeLmdbQuerySource.releaseCostModel(valueStore));
		failure = attemptClose(failure, mapGrowthCoordinator::shutdown);
		failure = attemptClose(failure, this::awaitReplayRetirements);
		failure = attemptClose(failure, this::awaitNativePublicationForShutdown);
		failure = attemptClose(failure, this::shutdownAndAwaitTripleStoreExecutor);
		if (directAdjacency != null) {
			failure = attemptClose(failure, directAdjacency::close);
		}
		failure = attemptClose(failure, this::shutdownAndAwaitIndexPreparationExecutor);
		failure = attemptClose(failure, this::cancelAndDrainScheduledBackgroundSampling);
		failure = attemptClose(failure, this::cancelAndDrainScheduledEstimatorPersist);
		failure = attemptClose(failure, this::shutdownAndAwaitEstimatorPersistExecutor);
		if (sketchBasedJoinEstimator != null) {
			failure = attemptClose(failure, sketchBasedJoinEstimator::close);
		}
		if (filterSelectivityStats != null) {
			failure = attemptClose(failure, filterSelectivityStats::persistIfDirty);
		}

		// A direct synchronous sink uses this same lifetime barrier for every native entry. Admission has
		// already closed, and admitted publication/native owners have completed before we acquire it.
		sinkStoreAccessLock.lock();
		try {
			if (valueStore != null && tripleStore != null) {
				failure = attemptClose(failure, () -> logLmdbStats(Level.INFO, "on shutdown"));
			}
			if (namespaceStore != null) {
				failure = attemptClose(failure, namespaceStore::close);
			}
			if (failure == null && valueStore != null && tripleStore != null && tripleStore.tracksNativeOwnership()) {
				try {
					valueStore.prepareCleanClose(tripleStore.trustedTransactionId());
				} catch (IOException unknownWriter) {
					valueStore.invalidateCleanCloseAfterUnknownTripleWriter();
					logger.warn("Cannot certify clean native state before close", unknownWriter);
				}
			}
			if (tripleStore != null) {
				failure = attemptClose(failure, () -> tripleStore.getTxnManager().close());
			}
			if (valueStore != null) {
				failure = attemptClose(failure, valueStore::closeReadTransactions);
				// Reader managers are already closed. Retain durable unused candidates for bounded post-ready or
				// explicit maintenance instead of admitting fresh liveness reads during shutdown.
				failure = attemptClose(failure, valueStore::close);
			}
			if (tripleStore != null) {
				failure = attemptClose(failure, tripleStore::close);
			}
			PersistentSetFactory<Long> factory = setFactory;
			setFactory = null;
			if (factory != null) {
				failure = attemptClose(failure, factory::close);
			}
		} finally {
			sinkStoreAccessLock.unlock();
		}

		if (failure != null) {
			logger.warn("Failed to close store", failure);
			if (failure instanceof SailException sailException) {
				throw sailException;
			}
			if (failure instanceof IOException ioException) {
				throw new SailException(ioException);
			}
			if (failure instanceof RuntimeException runtimeException) {
				throw runtimeException;
			}
			if (failure instanceof Error error) {
				throw error;
			}
			throw new SailException(failure);
		}
	}

	private void awaitNativePublicationForShutdown() {
		InterruptedException interruption = null;
		Throwable failure = null;
		try {
			publicationGate.lock();
			try {
				while (activePublications != 0 || publicationFinalizing) {
					try {
						publicationCompleted.await();
					} catch (InterruptedException cancellation) {
						if (interruption == null) {
							interruption = cancellation;
						} else {
							interruption.addSuppressed(cancellation);
						}
					}
				}
			} finally {
				publicationGate.unlock();
			}
			// Publication owners have settled. An unflushed direct sink can still retain an idle native
			// transaction; waiting for that sink to flush during shutdown would deadlock its owning caller.
			sinkStoreAccessLock.lock();
			try {
				Object idleOwner = storeTransactionOwner;
				if (storeTxnStarted.get()) {
					rollback();
				}
				if (idleOwner != null) {
					retireCheckpointWriterLeases(idleOwner);
				}
			} finally {
				sinkStoreAccessLock.unlock();
			}
		} catch (RuntimeException | Error cleanupFailure) {
			failure = cleanupFailure;
			throw cleanupFailure;
		} finally {
			// Idle asynchronous rollback can also join an owner and restore its interrupt. A later executor
			// may already be terminated, so it need not perform an interruptible wait that reports that signal.
			if (interruption == null && Thread.currentThread().isInterrupted()) {
				interruption = new InterruptedException("Interrupted during LMDB native shutdown cleanup");
			}
			if (interruption != null) {
				Thread.currentThread().interrupt();
				InterruptedSailException interruptedClose = new InterruptedSailException(
						"Interrupted while waiting for LMDB publication during shutdown", interruption);
				// A later executor may already be terminated and never consume the restored interrupt flag.
				// Record this join's outcome after idle cleanup, while allowing close to finish all other resources.
				if (failure == null) {
					throw interruptedClose;
				}
				failure.addSuppressed(interruptedClose);
			}
		}
	}

	@FunctionalInterface
	private interface CloseAction {
		void close() throws Exception;
	}

	private static Throwable attemptClose(Throwable failure, CloseAction action) {
		try {
			action.close();
		} catch (Throwable cleanupFailure) {
			if (failure == null) {
				return cleanupFailure;
			}
			if (failure != cleanupFailure) {
				failure.addSuppressed(cleanupFailure);
			}
		}
		return failure;
	}

	private void shutdownAndAwaitIndexPreparationExecutor() {
		indexPreparationExecutor.shutdown();
		try {
			while (!indexPreparationExecutor.awaitTermination(1, TimeUnit.SECONDS)) {
				logger.warn("Waiting for index preparation executor to terminate");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new InterruptedSailException(e);
		}
	}

	private void shutdownAndAwaitTripleStoreExecutor() {
		running.set(false);
		signalAsyncWaiters();
		tripleStoreExecutor.shutdown();
		InterruptedException interruption = null;
		try {
			while (true) {
				try {
					if (tripleStoreExecutor.awaitTermination(1, TimeUnit.SECONDS)) {
						break;
					}
					logger.warn("Waiting for triple store executor to terminate");
				} catch (InterruptedException failure) {
					// The worker can still own native transactions. Finish joining before close's finally blocks
					// release either environment, then restore and report the interruption.
					if (interruption == null) {
						interruption = failure;
					} else {
						interruption.addSuppressed(failure);
					}
				}
			}
			cancelQueuedOperations();
		} finally {
			if (interruption != null) {
				Thread.currentThread().interrupt();
			}
		}
		if (interruption != null) {
			throw new InterruptedSailException(interruption);
		}
	}

	private void shutdownAndAwaitEstimatorPersistExecutor() {
		estimatorPersistExec.shutdown();
		try {
			while (!estimatorPersistExec.awaitTermination(1, TimeUnit.SECONDS)) {
				logger.warn("Waiting for join estimator persist executor to terminate");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new InterruptedSailException(e);
		}
	}

	private void cancelAndDrainScheduledBackgroundSampling() {
		ScheduledFuture<?> future = backgroundSamplingFuture;
		if (future == null) {
			return;
		}
		if (future.cancel(false)) {
			return;
		}
		try {
			future.get();
		} catch (CancellationException e) {
			// Already cancelled by the scheduler or another close path.
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new InterruptedSailException(e);
		} catch (ExecutionException e) {
			logger.warn("Scheduled background filter sampling failed during close", e.getCause());
		}
	}

	private void cancelAndDrainScheduledEstimatorPersist() {
		ScheduledFuture<?> future = persistFuture;
		if (future == null) {
			return;
		}
		if (future.cancel(false)) {
			return;
		}
		try {
			future.get();
		} catch (CancellationException e) {
			// Already cancelled by the scheduler or another close path.
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new InterruptedSailException(e);
		} catch (ExecutionException e) {
			logger.warn("Scheduled join estimator persistence failed during close", e.getCause());
		}
	}

	private void startBackgroundFilterSampling() {
		if (filterSelectivityStats == null || backgroundRawSamplingMaxMillisPerCycle <= 0L) {
			logger.info(
					"LMDB background filter sampling not scheduled: filterStatsPresent={}, maxMillisPerCycle={}",
					filterSelectivityStats != null, backgroundRawSamplingMaxMillisPerCycle);
			return;
		}
		logger.info(
				"LMDB background filter sampling scheduled: initialDelayMillis={}, delayMillis={}, maxMillisPerCycle={}",
				estimatorPersistDelayMillis, estimatorPersistDelayMillis, backgroundRawSamplingMaxMillisPerCycle);
		backgroundSamplingFuture = estimatorPersistExec.scheduleWithFixedDelay(() -> {
			try {
				runBackgroundFilterSamplingCycle(backgroundRawSamplingMaxMillisPerCycle);
			} catch (RuntimeException e) {
				logger.warn("Background filter sampling cycle failed", e);
			}
		}, estimatorPersistDelayMillis, estimatorPersistDelayMillis, TimeUnit.MILLISECONDS);
	}

	int runBackgroundFilterSamplingCycle(long maxMillis) {
		if (filterSelectivityStats == null || maxMillis <= 0L) {
			logger.info(
					"LMDB background filter sampling cycle skipped: filterStatsPresent={}, maxMillis={}",
					filterSelectivityStats != null, maxMillis);
			return 0;
		}
		int pendingRequests = filterSelectivityStats.pendingBackgroundSamplingRequests();
		if (storeTxnStarted.get()) {
			if (pendingRequests > 0) {
				logger.info(
						"LMDB background filter sampling cycle skipped: store transaction active, pendingRequests={}",
						pendingRequests);
			}
			return 0;
		}
		// Paired read admission may wait for a publication whose writer needs sinkStoreAccessLock.
		// The admitted snapshots provide coherence without holding that ordinary writer guard.
		int sampled = filterSelectivityStats.runBackgroundSamplingCycle(maxMillis);
		if (sampled > 0) {
			scheduleEstimatorPersist();
		}
		return sampled;
	}

	private void persistEstimatorState() {
		if (sketchBasedJoinEstimator != null) {
			sketchBasedJoinEstimator.persistIfDirty();
		}
		if (filterSelectivityStats != null) {
			filterSelectivityStats.persistIfDirty();
		}
	}

	private void scheduleEstimatorPersist() {
		if (persistScheduled.compareAndSet(false, true)) {
			persistFuture = estimatorPersistExec.schedule(() -> {
				try {
					LmdbSailStore.this.persistEstimatorState();
				} finally {
					persistScheduled.set(false);
				}
			}, estimatorPersistDelayMillis, TimeUnit.MILLISECONDS);
		}
	}

	SailException wrapTripleStoreException() {
		if (multiThreadingActive && Thread.currentThread() != tripleStoreOwnerThread) {
			rollbackAsyncTransaction();
		}
		Throwable failure = tripleStoreException;
		if (failure instanceof Error fatal) {
			throw fatal;
		}
		if (failure instanceof SailException sail) {
			return sail;
		}
		if (failure instanceof RuntimeException runtime) {
			throw runtime;
		}
		return new SailException(failure);
	}

	/** Retained prepared-import callers observe the worker's complete failure, including fatal cleanup errors. */
	private void rethrowTripleStoreException() {
		if (multiThreadingActive) {
			rollbackAsyncTransaction();
		}
		Throwable failure = tripleStoreException;
		if (failure instanceof Error fatal) {
			throw fatal;
		}
		if (failure instanceof RuntimeException runtime) {
			throw runtime;
		}
		throw new SailException(failure);
	}

